<script lang="ts">
import { readMapData, type FloodDetail } from './flood';
import type { DetailGroup } from './detailGroups';
let { id, groups, releaseId, onlocation }: { id: string; groups: DetailGroup[]; releaseId?: string; onlocation: (id: string, point: [number, number] | null) => void } = $props();
type Section<T> = { status: 'loading' } | { status: 'unavailable' } | { status: 'ready'; data: T };
type Facts = { location?: { type: 'Point'; coordinates: [number, number] } | null; parcel: { parcel_number: string | null; address: string | null; mapped_acres: string | null; likely_vacant: boolean; updated_at: string }; source: string; source_parcel_id: string; owner_labels: null | Record<string, string | null>; sales: { date: string | null; amount: string | null; deed_book: string | null; deed_page: string | null }[] };
type Tax = { bills: Record<string, unknown>[]; delinquent_balances: Record<string, unknown>[]; reported_delinquent_total: string | null; pipeline: Record<string, unknown>[]; foreclosure_cases: Record<string, unknown>[]; note: string };
type Soil = { available: boolean; reason?: string; evidence_level: string; total_acres: number | null; uses: { use: string; rated: { rating: string; area: { acres: number } }[]; unrated: { acres: number }; uncovered: { acres: number }; ambiguous: { acres: number }; next_step: string }[]; warnings: string[]; freshness: { stale: boolean; reasons: string[]; fresh_until: string; refresh_failed_at: string | null } };
type Freshness = { stale: boolean; reasons: string[]; source_fetched_at: string | null; refresh_failed_at: string | null };
type Zoning = { available: boolean; total_acres: number | null; unmapped_acres: number; ambiguous_acres: number; zones: { jurisdiction: string; district_code: string | null; description: string | null; case_reference: string | null; source_date: string | null; area: { acres: number } }[]; jurisdictions: { name: string | null; area: { acres: number } }[]; freshness: Freshness };
type Roads = { available: boolean; state: string; distance_feet: number | null; search_radius_feet: number; county_edge_warning: boolean; ties: { name?: string | null; class?: string | null; status?: string | null; Name?: string | null; Class?: string | null; Status?: string | null }[]; freshness: Freshness };
let facts = $state<Section<Facts>>({ status: 'loading' });
let tax = $state<Section<Tax>>({ status: 'loading' });
type Vacancy = { available: boolean; tier: string; reason: string; facts?: Record<string, unknown> };
let vacancy = $state<Section<Vacancy>>({ status: 'loading' });
let soil = $state<Section<Soil>>({ status: 'loading' });
let flood = $state<Section<FloodDetail>>({ status: 'loading' });
let zoning = $state<Section<Zoning>>({ status: 'loading' });
let roads = $state<Section<Roads>>({ status: 'loading' });
function load<T>(id: string, section: string, assign: (state: Section<T>) => void) {
 const task = new AbortController();
 assign({ status: 'loading' });
 readMapData<T>(`/api/v1/parcels/${encodeURIComponent(id)}${section ? '/' + section : ''}`, task.signal).then(data => {
  if (!task.signal.aborted) assign({ status: 'ready', data });
 }).catch(() => { if (!task.signal.aborted) assign({ status: 'unavailable' }); });
 return () => task.abort();
}
$effect(() => { if (!id) return; const selected = id; return load<Facts>(selected, '', state => {
  facts = state;
  if (state.status === 'ready') onlocation(selected, state.data.location?.coordinates ?? null);
  if (state.status === 'unavailable') onlocation(selected, null);
 }); });
$effect(() => { if (!id || !groups.includes('tax')) return; return load<Tax>(id, 'tax', state => tax = state); });
$effect(() => { if (!id || !groups.includes('vacancy')) return; return load<Vacancy>(id, 'vacancy', state => vacancy = state); });
$effect(() => { if (!id || !groups.includes('soil')) return; return load<Soil>(id, 'soil', state => soil = state); });
$effect(() => { if (!id || !groups.includes('flood')) { flood = { status: 'loading' }; return; } return load<FloodDetail>(id, 'flood', state => flood = state); });
$effect(() => { if (!id || !groups.includes('zoning')) { zoning = { status: 'loading' }; return; } return load<Zoning>(id, 'zoning', state => zoning = state); });
$effect(() => { if (!id || !groups.includes('roads')) { roads = { status: 'loading' }; return; } return load<Roads>(id, 'roads', state => roads = state); });
const date = (value: string | null | undefined) => value ? value.slice(0, 10) : 'unknown date';
const text = (value: unknown) => value == null || value === '' ? 'unknown' : String(value);
const acres = (value: number) => value.toFixed(2);
</script>
{#snippet status<T>(section: Section<T>)}
 {#if section.status === 'loading'}<p>Loading evidence…</p>{:else if section.status === 'unavailable'}<p>Evidence is temporarily unavailable.</p>{/if}
{/snippet}
<section aria-label="Parcel identity"><h2>Parcel</h2>{@render status(facts)}
{#if facts.status === 'ready'}<p>{text(facts.data.parcel.parcel_number)} · {text(facts.data.parcel.address)}</p>{/if}</section>
{#if groups.includes('acreage')}<section aria-label="Acreage"><h2>Acreage</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>{text(facts.data.parcel.mapped_acres)} mapped acres</p><details><summary>Source and context</summary><p>{facts.data.source} · Updated {date(facts.data.parcel.updated_at)}. Mapped area is not a survey.</p></details>{/if}</section>{/if}
{#if groups.includes('ownership')}<section aria-label="Ownership"><h2>Ownership</h2>{@render status(facts)}{#if facts.status === 'ready'}<p>County owner labels: {facts.data.owner_labels ? `Entity ${text(facts.data.owner_labels.entity_name_indicator)} · Out-of-state mailing ${text(facts.data.owner_labels.out_of_state_mailing)}` : 'unknown'}. {facts.data.sales.length} stored sales.</p><details><summary>Stored labels and sales</summary>{#if facts.data.owner_labels}<p>Mailing state: {text(facts.data.owner_labels.mailing_state)} · Matched suffix: {text(facts.data.owner_labels.matched_suffix)}</p>{/if}<ul>{#each facts.data.sales as sale}<li>{date(sale.date)} · ${text(sale.amount)} · Deed {text(sale.deed_book)}/{text(sale.deed_page)}</li>{/each}</ul><p>Source: {facts.data.source}. Labels are inferred from county records, not verified contacts.</p></details>{/if}</section>{/if}
{#if groups.includes('tax')}<section aria-label="Tax evidence"><h2>Stored tax evidence</h2>{@render status(tax)}{#if tax.status === 'ready'}<p>Reported delinquent total: {tax.data.reported_delinquent_total == null ? 'unknown' : '$' + tax.data.reported_delinquent_total}. {tax.data.note}</p><details><summary>Stored record counts</summary><p>{tax.data.bills.length} bills · {tax.data.delinquent_balances.length} delinquent balances · {tax.data.pipeline.length} pipeline records · {tax.data.foreclosure_cases.length} foreclosure cases. Confirm amounts against county records.</p></details>{/if}</section>
{/if}{#if groups.includes('vacancy')}<section aria-label="Vacancy evidence"><h2>Vacancy evidence</h2>{@render status(vacancy)}{#if vacancy.status === 'ready'}<p>Tier: {vacancy.data.tier} · Reason: {vacancy.data.reason.replaceAll('_', ' ')}</p><details><summary>Evidence context</summary><p>Stored vacancy classification is provisional. Confirm on site and against current county records.</p></details>{/if}</section>
{/if}{#if groups.includes('soil')}<section aria-label="Soil assessment"><h2>Soil assessment</h2>{@render status(soil)}{#if soil.status === 'ready'}{#if !soil.data.available}<p>No published soil assessment. {text(soil.data.reason)}</p>{:else}<p>USDA mapped soil evidence, not septic approval. Evidence level: {soil.data.evidence_level} · Parcel acres: {text(soil.data.total_acres)}</p><details><summary>Mapped soil ratings and limitations</summary>{#each soil.data.uses as use}<h3>{use.use.replaceAll('_', ' ')}</h3><p>{use.rated.map(r => `${r.rating}: ${acres(r.area.acres)} acres`).join('; ') || 'No rated area'} · Unrated {acres(use.unrated.acres)} · Uncovered {acres(use.uncovered.acres)} · Ambiguous {acres(use.ambiguous.acres)} acres.</p><p>{use.next_step}</p>{/each}{#each soil.data.warnings as warning}<p>{warning}</p>{/each}<p>{soil.data.freshness.stale ? 'Stale' : 'Current as of stored source'} soil evidence · Fresh until {date(soil.data.freshness.fresh_until)}{soil.data.freshness.refresh_failed_at ? ` · Refresh failed ${date(soil.data.freshness.refresh_failed_at)}` : ''}{soil.data.freshness.reasons.length ? ` · ${soil.data.freshness.reasons.join(', ')}` : ''}</p></details>{/if}{/if}</section>
{/if}{#if groups.includes('flood')}<section aria-label="Flood evidence"><h2>FEMA flood evidence</h2>{@render status(flood)}{#if flood.status === 'ready'}{#if releaseId && flood.data.release?.id !== releaseId}<p>FEMA data changed. Move the map to load the current release.</p>{:else if flood.data.status === 'no_release'}<p>No FEMA release is stored.</p>{:else if flood.data.status === 'missing_geometry'}<p>Parcel geometry is unavailable.</p>{:else if flood.data.status === 'available'}<p>FEMA archive issue date: {date(flood.data.release?.issued_at)} · Unknown coverage: {acres(flood.data.acres.unknown)} acres of {acres(flood.data.acres.parcel)} acres · Mapped floodway: {acres(flood.data.acres.floodway)} acres</p><h3>Mapped zones</h3>{#if flood.data.zones.length}<ul>{#each flood.data.zones as zone}<li>Zone {zone.code || 'unknown'}{zone.subtype ? ` · ${zone.subtype}` : ''}: {acres(zone.acres)} acres</li>{/each}</ul>{:else}<p>No mapped zone overlaps this parcel.</p>{/if}<h3>FEMA panels</h3>{#if flood.data.panels.length}<ul>{#each flood.data.panels as panel}<li>{panel.number} · {panel.effective_date ?? 'Effective date unavailable'}</li>{/each}</ul>{:else}<p>No panel overlaps this parcel.</p>{/if}<p>Zones can overlap. Do not add their areas. A blank area is not proof that the parcel is free from flood risk.</p>{/if}{/if}</section>{/if}
{#if groups.includes('zoning')}<section aria-label="Zoning evidence"><h2>Zoning and jurisdiction</h2>{@render status(zoning)}{#if zoning.status === 'ready'}{#if !zoning.data.available}<p>No published zoning assessment.</p>{:else}<p>Parcel area: {text(zoning.data.total_acres)} acres · Unmapped: {acres(zoning.data.unmapped_acres)} · Ambiguous: {acres(zoning.data.ambiguous_acres)} acres. Check local ordinances for permitted uses.</p><ul>{#each zoning.data.zones as zone}<li>{zone.jurisdiction} · {text(zone.district_code)} · {text(zone.description)} · {acres(zone.area.acres)} acres{#if zone.case_reference}<p>Case reference: {zone.case_reference}</p>{/if}{#if zone.source_date}<p>Source record date: {zone.source_date}</p>{/if}</li>{/each}{#each zoning.data.jurisdictions as item}<li>{text(item.name)} · {acres(item.area.acres)} acres</li>{/each}</ul>{/if}<p>{zoning.data.freshness.stale ? 'Stale' : 'Current'} · Source fetched {date(zoning.data.freshness.source_fetched_at)}{zoning.data.freshness.refresh_failed_at ? ' · Refresh failed ' + date(zoning.data.freshness.refresh_failed_at) : ''} · {zoning.data.freshness.reasons.join(', ')}</p>{/if}</section>{/if}
{#if groups.includes('roads')}<section aria-label="Road evidence"><h2>Roads</h2>{@render status(roads)}{#if roads.status === 'ready'}<p>{roads.data.available ? roads.data.state.replaceAll('_', ' ') : 'No published road assessment'} · {roads.data.distance_feet == null ? 'Distance unknown' : `${roads.data.distance_feet.toFixed(0)} feet to mapped road`} · Search radius {roads.data.search_radius_feet} feet. Distance does not establish legal access.</p>{#if roads.data.county_edge_warning}<p>County edge may limit coverage.</p>{/if}<ul>{#each roads.data.ties as road}<li>{text(road.name ?? road.Name)} · {text(road.class ?? road.Class)} · {text(road.status ?? road.Status)}</li>{/each}</ul><p>{roads.data.freshness.stale ? 'Stale' : 'Current'} · Source fetched {date(roads.data.freshness.source_fetched_at)}{roads.data.freshness.refresh_failed_at ? ' · Refresh failed ' + date(roads.data.freshness.refresh_failed_at) : ''} · {roads.data.freshness.reasons.join(', ')}</p>{/if}</section>{/if}
<style>section { border-bottom: 1px solid var(--border); padding: 10px 0; overflow-wrap: anywhere; } h2 { font-size: 15px; font-weight: 650; } h3 { font-size: 13px; font-weight: 600; margin-top: 8px; } p,li { font-size: 12px; line-height: 1.5; } ul { padding-left: 18px; }</style>
